declare(strict_types=1); require __DIR__ . '/../../config/database.php'; require_once __DIR__ . '/../Services/Auth/auth.php'; require_once __DIR__ . '/../Services/Leave/alur-persetujuan-izin.php'; wajibRole('pic','koordinator','manager','direktur','admin','superadmin');
$where=roleOperasional()?'d.department_id = '.(int)departmentIdPengguna():'1=1'; $data=mysqli_query($conn,"SELECT d.id,d.nominal,d.deskripsi,d.status,d.catatan_persetujuan,d.created_at,k.emp_id,k.employee_name,pemroses.nama AS nama_pemroses,pemroses.role AS role_pemroses FROM denda_reports d INNER JOIN karyawan k ON k.id=d.karyawan_id LEFT JOIN users pemroses ON pemroses.id=d.diproses_oleh_user_id WHERE {$where} ORDER BY d.created_at DESC LIMIT 100"); $judulHalaman='Notifikasi Denda'; $subjudulHalaman='Pengajuan denda dan perubahan status terbaru.'; $halamanAktif='denda'; require __DIR__ . '/../../resources/views/layouts/atas.php'; ?>
<section class="data-card notification-page-card"><div class="data-card-header"><h2>Notifikasi Denda</h2><p>Pengajuan denda beserta status keputusan.</p></div><div class="notification-list"><?php if($data&&mysqli_num_rows($data)>0):while($r=mysqli_fetch_assoc($data)): ?><article class="notification-item"><strong>Denda ID <?= (int)$r['id']; ?> — <?= htmlspecialchars($r['emp_id'].' - '.$r['employee_name']); ?></strong><span>Nominal: Rp <?= number_format((float)$r['nominal'],0,',','.'); ?></span><span>Status: <?= htmlspecialchars((string) ($r['status'] === 'disetujui' ? 'Disetujui ' . labelRole((string) ($r['role_pemroses'] ?? 'manager')) : ($r['status'] === 'ditolak' ? 'Ditolak' : ($r['status'] === 'menunggu_koordinator' ? 'Menunggu Koordinator' : ($r['status'] === 'menunggu_manager' ? 'Menunggu Manager' : 'Draft'))))); ?></span><span><b>Keterangan:</b> <?= nl2br(htmlspecialchars($r['deskripsi'])); ?></span><span><b>Keputusan:</b> <?= htmlspecialchars(trim((string) ($r['nama_pemroses'] ?? '')) !== '' ? $r['nama_pemroses'] . (trim((string) ($r['catatan_persetujuan'] ?? '')) !== '' ? ' — ' . $r['catatan_persetujuan'] : '') : 'Belum ada keputusan'); ?></span><small><?= htmlspecialchars($r['created_at']); ?></small></article><?php endwhile;else: ?><p class="notification-empty">Belum ada notifikasi denda.</p><?php endif; ?></div></section><?php require __DIR__ . '/../../resources/views/layouts/bawah.php'; ?>
